import {HandleInput as Fundamental} from "./2Managing State/4zBaseConcept"
import Sub from "./subReLearn"
import Custom from "./customComponent"
import "./ReLearn.css"

import { useState } from "react"

export default function() {
  const [arr, setArr] = useState([{a: "wow", b: "real"},{a: 1, b:2}])
  const [selectB, setSelectB] = useState("real")
  const selectedItem = arr.find(obj => obj.b == selectB)
  return <>
  {Object.entries(selectedItem).map(([a,b])=> a + " " + b + (a=="b" ? "" : ", "))}
  </>
}

